msg.method = 'GET';
msg.url = (env.get('BRIDGE_URL') || 'http://127.0.0.1:8081') + '/devices';
delete msg.payload;
return msg;

msg.method = 'GET';
msg.url = (env.get('BRIDGE_URL') || 'http://127.0.0.1:8081') + '/operations';
delete msg.payload;
return msg;

const id = env.get('DEVICE_ID') || 'heltec-labredes';
const devices = Array.isArray(msg.payload) ? msg.payload : [];
const device = devices.find(item => item.device_id === id) || null;
flow.set('dashboardDevice', device);
msg.topic = 'state';
msg.payload = { device, operation: flow.get('dashboardOperation') || null };
return msg;

const id = env.get('DEVICE_ID') || 'heltec-labredes';
const operations = Array.isArray(msg.payload) ? msg.payload : [];
const operation = operations.find(item => item.device_id === id) || null;
flow.set('dashboardOperation', operation);
msg.topic = 'state';
msg.payload = { device: flow.get('dashboardDevice') || null, operation };
return msg;

msg.filename = env.get('DASHBOARD_TEMPLATE');
if (!msg.filename) { node.error('Falta DASHBOARD_TEMPLATE', msg); return null; }
return msg;

msg.ui_update = { format: msg.payload };
msg.topic = 'template';
msg.payload = null;
return msg;

const endpoint = env.get('LESHAN_ENDPOINT') || 'smartcitynet-heltec-labredes';
const base = env.get('LESHAN_URL') || 'http://127.0.0.1:8080';
const action = msg.action;
const lightResources = { 'light-front': 23, 'light-rear': 24, 'light-parking': 25 };
let resource;
let type;
let value;
if (action === 'alert') {
  resource = 11; type = 'BOOLEAN'; value = msg.payload === true;
} else if (action === 'interval') {
  value = Number(msg.payload);
  if (!Number.isInteger(value) || value < 15 || value > 86400) {
    msg.topic = 'feedback';
    msg.payload = { ok: false, action, text: 'Intervalo inválido: use un entero entre 15 y 86400 segundos.' };
    return [null, msg];
  }
  resource = 0; type = 'INTEGER'; value = String(value);
} else if (Object.hasOwn(lightResources, action)) {
  resource = lightResources[action]; type = 'BOOLEAN'; value = msg.payload === true;
} else {
  return [null, null];
}
msg.commandAction = action;
msg.method = 'PUT';
msg.url = `${base}/api/clients/${encodeURIComponent(endpoint)}/32769/0/${resource}`;
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { kind: 'singleResource', id: resource, type, value };
return [msg, null];

const code = Number(msg.statusCode);
const body = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
const httpOk = code >= 200 && code < 300;
const ok = httpOk && body.success === true && body.failure !== true;
const labels = {
  alert: 'alerta remota',
  interval: 'intervalo de transmisión',
  'light-front': 'luz frontal',
  'light-rear': 'luz trasera',
  'light-parking': 'luces de parqueo'
};
const command = labels[msg.commandAction] || 'recurso';
const result = body.status || msg.statusCode || 'sin respuesta';
msg.topic = 'feedback';
msg.payload = {
  ok,
  action: msg.commandAction,
  text: ok
    ? `Leshan aceptó la escritura de ${command}. Esperando confirmación de la Heltec…`
    : `Leshan rechazó la escritura de ${command} (${result}).`
};
return msg;
